exercises.solution:
package main

import (
    "fmt"
    "strings"
)

func main() {
    text := "Hello, World!"

    fmt.Println("Contains:", strings.Contains(text, "Hello"))

    replaced := strings.Replace(text, "World", "Go", 1)
    fmt.Println("Replaced:", replaced)

    parts := strings.Split("a,b,c", ",")
    fmt.Println("First:", parts[0])
}

